def count_distinct_length_three_substrings(s):
    counts = {}
    answer = 0
    for index, char in enumerate(s):
        counts[char] = counts.get(char, 0) + 1
        if index >= 3:
            leaving = s[index - 3]
            counts[leaving] -= 1
            if counts[leaving] == 0:
                del counts[leaving]
        if index >= 2 and len(counts) == 3:
            answer += 1
    return answer

